# ==============================================================================# 032_RUNTIME_KERNEL.py# ==============================================================================import sqlite3import subprocessimport sysfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS runtime(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    service TEXT,    module TEXT,    status TEXT,    execution_time REAL)""")conn.commit()cur.execute("""SELECTservice_name,moduleFROM servicesORDER BY id""")services = cur.fetchall()print("="*80)print("RUNTIME KERNEL")print("="*80)for s in services:    module = ROOT / s["module"]    if module.exists():        status = "READY"    else:        status = "NOT_FOUND"    cur.execute("""    INSERT INTO runtime(        timestamp,        service,        module,        status,        execution_time    )    VALUES(?,?,?,?,?)    """,(        datetime.now().isoformat(),        s["service_name"],        s["module"],        status,        0.0    ))    conn.commit()    print(f"{s['service_name']:<22} {status}")print("="*80)cur.execute("""SELECTCOUNT(*) totalFROM runtime""")print("SERVIÃ‡OS REGISTRADOS:",cur.fetchone()["total"])print("="*80)conn.close()

